/**
 * Draws a card in the design language of `created-svg_graphic-api.svg`.
 *
 * Generated by the graphic-designer helper's `design-language` skill. The
 * language lives in the constants at the top - change it there, in one place,
 * rather than in the composition below. `DESIGN_LANGUAGE.md` beside this
 * script says where every number came from and which are readings rather than
 * measurements.
 *
 *   node make-created-svg_graphic-api.mjs --title "Acme Corp" --out ./out
 *
 * ---------------------------------------------------------------------------
 * THIS COPY IS A TEST FIXTURE. Do not edit it to change a graphic.
 *
 * The live skill is the one the helper wrote into the AI tool's folder
 * (`.claude/skills/created-svg_graphic-api/`), and that is the copy to edit.
 * This one is frozen so `test/generated-skill.test.ts` has something tracked to
 * render - a test cannot depend on a file that is not in the repository, and
 * the generated skill lives in a folder git ignores.
 *
 * Provenance: generated 2026-09-11 by
 *   /graphic-designer:design-language test/graphic-design-api/created-svg_graphic-api.svg
 * from `test/graphic-design-api/created-svg_graphic-api.svg`, then corrected
 * twice - a missing paper footer, and code tokens advanced by `measureText`
 * rather than by the monospace metric the SVG's own font uses.
 *
 * Re-baselining is deliberate: copy the live skill over this one, run
 * `npm test`, and read what changed. A fixture that drifts silently is worse
 * than one that is out of date loudly.
 *
 * Re-baselined 2026-09-12 to carry brand slots. `compose` and
 * `composeCheatsheet` now take an optional `brand`, resolved from
 * `references/resources.md` by `scripts/brand-resources.mjs`; without one every
 * slot falls back to exactly what this script drew before, which is why the
 * existing standards in `test/generated-skill.test.ts` still hold.
 * ---------------------------------------------------------------------------
 */

import { existsSync } from 'node:fs';
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import { brandInstructions, resolveBrand } from './brand-resources.mjs';

/** The palette, in roles. The shares are the 60-30-10 the source measured. */
const PALETTE = {
  ground: '#000133',
  paper: '#ffffff',
  accent: '#4cae50',
  ink: '#414042',
};

/** A 1.250 major third, rounded to the intent behind the measured sizes. */
const TYPE = {
  display: 20.5,
  head: 16.5,
  small: 7.5,
  caption: 6,
  displayFamily: "'Alternate Gothic No1 D', 'Oswald', sans-serif",
  textFamily: "'Futura PT', Futura, 'Century Gothic', sans-serif",
};

/**
 * The code-token palette.
 *
 * The design language reserves these for tokens inside a code panel and
 * nowhere else - they carry 42% of the source's declared colours and almost
 * none of its area, which is exactly what a syntax palette looks like. Using
 * one of them for a rule or a plate would break the language.
 */
const SYNTAX = {
  tag: '#8ce632',
  attr: '#fdc83a',
  value: '#f8f5ae',
  comment: '#b4bec8',
  plain: '#aef8b7',
  text: '#ffffff',
};

const PAGE = { width: 360, height: 360, margin: 16 };
const STROKE = { rule: 2, bar: 4.5 };
const MONO = "'Courier New', Courier, monospace";

/**
 * Advance of one character in the monospace family above, as a fraction of the
 * font size. Courier and Courier New are both exactly 0.6 em.
 *
 * This constant exists because `measureText` cannot answer the question.
 * `measureText` measures the API's *built-in* font - the proportional
 * single-stroke alphabet the rasterizer draws - and that is the right metric
 * for a text block, where both renderers lay out from the same table. It is
 * the wrong metric for placing tokens side by side in a family the SVG names
 * itself: the built-in font is narrower than Courier New by up to 10 units on
 * a line this size, so tokens advanced by it land short and the next one
 * prints over the last. Positioning against a named font needs that font's
 * own metric, and for a monospace family that metric is one number.
 */
const MONO_ADVANCE = 0.6;

/** Width of a run of monospace text, in composition units. */
function monoWidth(text, size) {
  return text.length * size * MONO_ADVANCE;
}

/** The skill folder, so `references/resources.md` is found beside it. */
const SKILL_DIR = resolve(dirname(fileURLToPath(import.meta.url)), '..');

/**
 * A brand with nothing behind it.
 *
 * Every composing function takes a brand and this is the default, so a caller
 * who has no `resources.md` - and every existing caller, including the test
 * suite's own renderer - gets the composition this script drew before brand
 * slots existed. That is the property worth keeping: configuring a brand adds
 * marks to a page that was already complete without them.
 */
const NO_BRAND = {
  has: () => false,
  textFor: () => null,
  place: (list, key, box) => ({ placed: false, mode: 'none', box, notes: [] }),
};

/**
 * Finds the napkin-sketch graphic-design API: the package when it is a
 * dependency, otherwise a clone's build output. Mirrors how the analyzer finds
 * it, so this script runs in the same places that one does.
 */
async function loadApi() {
  try {
    return await import('napkin-sketch');
  } catch {
    // Not installed as a package; look for a clone's build output instead.
  }
  let dir = dirname(fileURLToPath(import.meta.url));
  for (let i = 0; i < 10; i++) {
    const built = join(dir, 'dist', 'api', 'index.js');
    if (existsSync(built)) return import(pathToFileURL(built).href);
    const up = dirname(dir);
    if (up === dir) break;
    dir = up;
  }
  throw new Error(
    'graphic-design API not found. Run `npm run build` in a napkin-sketch clone, or install napkin-sketch.'
  );
}

/**
 * Composes the card.
 *
 * Horizontal bands, which is what the source does and what keeps it legible
 * small: a title on the ground, a rule, a white plate, a panel, a footer bar.
 */
export function compose(api, { title, heading, body, footer, brand = NO_BRAND }) {
  const design = api.createComposition({
    width: PAGE.width,
    height: PAGE.height,
    background: PALETTE.ground,
    title: heading,
  });

  // The title band carries the brand mark at its right, in the box the source
  // asset's own `logo` layer occupies. With no asset configured the band is
  // just the title, which is what this card was before.
  const logoSlot = { x: PAGE.width - PAGE.margin - 45, y: 13, width: 45, height: 24 };
  brand.place(design, 'logo', logoSlot, { fit: 'contain', fallback: false });

  design.text({
    x: PAGE.margin,
    y: 32,
    text: brand.textFor('brandName') ?? title,
    fontFamily: TYPE.displayFamily,
    fontSize: TYPE.display,
    letterSpacing: 1.2,
    transform: 'uppercase',
    maxWidth: brand.has('logo') ? logoSlot.x - PAGE.margin - 8 : undefined,
    fill: PALETTE.paper,
  });

  design.line({
    x1: PAGE.margin,
    y1: 44,
    x2: PAGE.width - PAGE.margin,
    y2: 44,
    stroke: PALETTE.accent,
    strokeWidth: STROKE.rule,
  });

  // A plate interrupts the ground. Square corners: the source declares none.
  design.rect({
    x: PAGE.margin,
    y: 56,
    width: PAGE.width - PAGE.margin * 2,
    height: 44,
    fill: PALETTE.paper,
  });
  design.text({
    x: PAGE.width / 2,
    y: 76,
    text: heading,
    fontFamily: TYPE.textFamily,
    fontSize: TYPE.small,
    fontWeight: 'bold',
    align: 'center',
    fill: PALETTE.ink,
  });
  design.text({
    x: PAGE.width / 2,
    y: 90,
    text: footer,
    fontFamily: TYPE.textFamily,
    fontSize: TYPE.caption,
    align: 'center',
    fill: PALETTE.ink,
  });

  // The accent marks where the panel begins, not what is in it.
  design.rect({
    x: PAGE.margin,
    y: 116,
    width: 6,
    height: 136,
    fill: PALETTE.accent,
  });
  design.rect({
    x: PAGE.margin + 16,
    y: 116,
    width: PAGE.width - PAGE.margin * 2 - 16,
    height: 136,
    fill: PALETTE.ground,
    stroke: PALETTE.accent,
    strokeWidth: 1,
  });
  design.text({
    x: PAGE.margin + 26,
    y: 134,
    text: body,
    fontFamily: TYPE.textFamily,
    fontSize: TYPE.caption,
    lineHeight: 1.6,
    maxWidth: PAGE.width - PAGE.margin * 2 - 36,
    baseline: 'top',
    fill: PALETTE.paper,
  });

  // The footer is paper, not ground. Without it the page measures ~83% ground
  // against the source's ~56%, which the analyzer catches immediately - the
  // ratio is the part of a design language that is easiest to lose.
  design.rect({
    x: 0,
    y: PAGE.height - 48,
    width: PAGE.width,
    height: 48,
    fill: PALETTE.paper,
  });
  design.rect({
    x: 0,
    y: PAGE.height - 48 - STROKE.bar,
    width: PAGE.width,
    height: STROKE.bar,
    fill: PALETTE.accent,
  });
  footerBand(design, brand, footer);

  return design;
}

/**
 * Sets the footer band: a linked asset if one is configured, otherwise type.
 *
 * The source asset puts a `linkedMedia` strip here, so a configured brand's
 * footer artwork belongs in the same place. `fallback: false` matters - the
 * alternative to a placed strip is a line of type, not a monogram, and a slot
 * that drew a monogram here would be filling the space rather than reading the
 * design language.
 */
function footerBand(design, brand, footer) {
  const band = { x: PAGE.margin, y: PAGE.height - 40, width: PAGE.width - PAGE.margin * 2, height: 26 };
  const placed = brand.place(design, 'linkedMedia', band, { fit: 'contain', fallback: false });
  if (placed.placed) return placed;

  design.text({
    x: PAGE.margin,
    y: PAGE.height - 20,
    text: brand.textFor('domain') ?? footer,
    fontFamily: TYPE.textFamily,
    fontSize: TYPE.small,
    transform: 'uppercase',
    letterSpacing: 0.6,
    fill: PALETTE.ink,
  });
  return placed;
}

/**
 * Fits a display line into the width available to it.
 *
 * A title is meant to be a word - HTML, CSS, GIT - and a caller who passes a
 * sentence should get a smaller title rather than one drawn off the side of the
 * page. Two steps, in this order, because the design language constrains both:
 *
 * 1. Step down the type scale. Only sizes on the 1.250 major third are allowed,
 *    so this tries 20.5 then 16.5 and stops - there is no display size below
 *    that, and inventing one would break the language to save a layout.
 * 2. Truncate. When even the smaller step does not fit, the line is cut and
 *    ended with an ellipsis.
 *
 * Measured with `measureText`, the built-in alphabet, which is what the raster
 * draws. The SVG sets a condensed face that is narrower still, so a line that
 * fits here fits there too. Conservative in the one direction that is safe.
 */
function fitDisplay(api, text, available, letterSpacing) {
  const measure = (value, size) => api.measureText(value, { fontSize: size, letterSpacing });

  for (const size of [TYPE.display, TYPE.head]) {
    if (measure(text, size) <= available) return { text, size };
  }

  const size = TYPE.head;
  let cut = text;
  while (cut.length > 1 && measure(`${cut}...`, size) > available) {
    cut = cut.slice(0, -1);
  }
  return { text: `${cut.trimEnd()}...`, size };
}

/**
 * Draws one line of code as coloured tokens.
 *
 * Each token is its own text element, advanced by {@link monoWidth} rather
 * than by `measureText` - see that constant for why. Colour comes from
 * {@link SYNTAX} only.
 */
function codeLine(design, api, x, baseline, tokens, size) {
  let pen = x;
  for (const [text, tone] of tokens) {
    if (text) {
      design.text({
        x: pen,
        y: baseline,
        text,
        fontFamily: MONO,
        fontSize: size,
        fill: SYNTAX[tone] ?? SYNTAX.text,
      });
    }
    pen += monoWidth(text, size);
  }
  return pen;
}

/**
 * Composes a cheatsheet: the same bands as the card, with a code panel where
 * the card has a paragraph.
 *
 * This is the layout the source asset itself uses - a title band, a rule, a
 * plate carrying the heading, a panel of syntax-coloured code held off the
 * left edge by an accent margin, and a paper footer. The card and the
 * cheatsheet are the same language wearing different content.
 */
export function composeCheatsheet(api, { title, heading, subheading, rows, footer, brand = NO_BRAND }) {
  const design = api.createComposition({
    width: PAGE.width,
    height: PAGE.height,
    background: PALETTE.ground,
    id: 'Cheatsheet',
    title: heading,
  });

  // The title shares the band with the badge, so it gets the space to the left
  // of it and no more. `transform: 'uppercase'` is applied at render time, and
  // upper case is wider, so the fit is measured against the upper-cased string
  // rather than against what the caller passed.
  const badgeX = PAGE.width - PAGE.margin - 54;
  const fitted = fitDisplay(api, title.toUpperCase(), badgeX - PAGE.margin - 8, 1.2);
  const badge = { x: badgeX, y: 16, width: 54, height: 20 };
  design.text({
    x: PAGE.margin,
    y: 32,
    text: fitted.text,
    fontFamily: TYPE.displayFamily,
    fontSize: fitted.size,
    letterSpacing: 1.2,
    transform: 'uppercase',
    fill: PALETTE.paper,
  });

  // The badge is the source's own device: a small accent block in the title
  // band, marking the topic. Structure, not content - which is exactly why a
  // configured logo goes here instead. Same box, same role on the page.
  if (!brand.place(design, 'logo', badge, { fit: 'contain', fallback: false }).placed) {
    design.rect({ ...badge, fill: PALETTE.accent });
    design.text({
      x: PAGE.width - PAGE.margin - 27,
      y: 30,
      text: 'cheatsheet',
      fontFamily: TYPE.textFamily,
      fontSize: TYPE.caption,
      align: 'center',
      transform: 'uppercase',
      letterSpacing: 0.4,
      fill: PALETTE.ground,
    });
  }

  design.line({
    x1: PAGE.margin,
    y1: 44,
    x2: PAGE.width - PAGE.margin,
    y2: 44,
    stroke: PALETTE.accent,
    strokeWidth: STROKE.rule,
  });

  design.rect({ x: PAGE.margin, y: 52, width: PAGE.width - PAGE.margin * 2, height: 40, fill: PALETTE.paper });
  design.text({
    x: PAGE.width / 2,
    y: 70,
    text: heading,
    fontFamily: TYPE.textFamily,
    fontSize: TYPE.small,
    fontWeight: 'bold',
    align: 'center',
    fill: PALETTE.ink,
  });
  design.text({
    x: PAGE.width / 2,
    y: 84,
    text: subheading,
    fontFamily: TYPE.textFamily,
    fontSize: TYPE.caption,
    align: 'center',
    fill: PALETTE.ink,
  });

  // The panel: an accent margin, then the code held off it.
  const panelTop = 102;
  const panelHeight = 198;
  design.rect({ x: PAGE.margin, y: panelTop, width: 8, height: panelHeight, fill: PALETTE.accent });
  design.rect({
    x: PAGE.margin + 18,
    y: panelTop,
    width: PAGE.width - PAGE.margin * 2 - 18,
    height: panelHeight,
    fill: PALETTE.ground,
    stroke: PALETTE.accent,
    strokeWidth: 1,
  });

  // The line step is derived from the row count rather than fixed, so a longer
  // listing tightens instead of running out under the footer. A cheatsheet that
  // silently loses its last line is worse than one that is a little dense.
  const step = Math.min(14, (panelHeight - 20) / Math.max(rows.length, 1));
  rows.forEach((tokens, i) => {
    codeLine(design, api, PAGE.margin + 28, panelTop + 14 + i * step, tokens, TYPE.caption);
  });

  design.rect({ x: 0, y: PAGE.height - 48, width: PAGE.width, height: 48, fill: PALETTE.paper });
  design.rect({
    x: 0,
    y: PAGE.height - 48 - STROKE.bar,
    width: PAGE.width,
    height: STROKE.bar,
    fill: PALETTE.accent,
  });
  footerBand(design, brand, footer);

  return design;
}

/** The HTML reference the cheatsheet mode draws when nothing else is given. */
const HTML_ROWS = [
  [['<!DOCTYPE html>', 'comment']],
  [['<html', 'tag'], [' lang', 'attr'], ['="en"', 'value'], ['>', 'tag']],
  [['  <head>', 'tag']],
  [['    <meta', 'tag'], [' charset', 'attr'], ['="utf-8"', 'value'], ['>', 'tag']],
  [['    <title>', 'tag'], ['Page title', 'text'], ['</title>', 'tag']],
  [['    <link', 'tag'], [' rel', 'attr'], ['="stylesheet"', 'value'], [' href', 'attr'], ['="a.css"', 'value'], ['>', 'tag']],
  [['  </head>', 'tag']],
  [['  <body>', 'tag']],
  [['    <h1', 'tag'], [' id', 'attr'], ['="top"', 'value'], ['>', 'tag'], ['Heading', 'text'], ['</h1>', 'tag']],
  [['    <p', 'tag'], [' class', 'attr'], ['="lead"', 'value'], ['>', 'tag'], ['Paragraph.', 'text'], ['</p>', 'tag']],
  [['    <a', 'tag'], [' href', 'attr'], ['="/docs"', 'value'], ['>', 'tag'], ['Link', 'text'], ['</a>', 'tag']],
  [['    <img', 'tag'], [' src', 'attr'], ['="logo.png"', 'value'], [' alt', 'attr'], ['="Logo"', 'value'], ['>', 'tag']],
  [['    <ul>', 'tag'], ['<li>', 'tag'], ['Item', 'text'], ['</li>', 'tag'], ['</ul>', 'tag']],
  [['  </body>', 'tag']],
  [['</html>', 'tag']],
];

async function run() {
  const args = process.argv.slice(2);
  if (args.includes('--help')) {
    console.log(
      'make-created-svg_graphic-api [--cheatsheet] --title <t> --heading <h> --body <b> --footer <f> --out <dir> --name <basename>'
    );
    return;
  }
  const flag = (name, fallback) => {
    const i = args.indexOf(`--${name}`);
    return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
  };

  const api = await loadApi();
  const cheatsheet = args.includes('--cheatsheet');

  const brand = await resolveBrand({ api, path: flag('resources'), skillDir: SKILL_DIR });

  const design = cheatsheet
    ? composeCheatsheet(api, {
        brand,
        title: flag('title', 'HTML'),
        heading: flag('heading', 'HTML Document Structure Starting Point'),
        subheading: flag('subheading', 'Head, Body, and the Tags Worth Memorizing'),
        rows: HTML_ROWS,
        footer: flag('footer', 'jane.doe@example.com'),
      })
    : compose(api, {
        brand,
        title: flag('title', 'Acme Corp'),
        heading: flag('heading', 'Quarterly Summary Starting Point'),
        body: flag(
          'body',
          'Prepared by Jane Doe. Every number in this panel comes from the measured design language beside this script, so a change to the language is one edit rather than a search.'
        ),
        footer: flag('footer', 'jane.doe@example.com'),
      });

  // Both formats come off the one composition, so the SVG and the PNG are the
  // same graphic rather than two renders that can drift.
  //
  // The raster is drawn at 3x by default, and that is not a retina nicety. The
  // caption size in this language is 6 units, and the built-in single-stroke
  // alphabet draws a 6-unit glyph with a 0.45-unit stroke - under one device
  // pixel at 1x, so it anti-aliases into grey mush and the code panel reads as
  // texture rather than text. At 3x the same stroke is 1.35 pixels and the
  // panel is legible. The design language is unchanged; only the sampling is.
  const out = resolve(flag('out', './out'));
  const name = flag('name', cheatsheet ? 'cheatsheet' : 'card');
  const scale = Number(flag('scale', '3')) || 3;
  await mkdir(out, { recursive: true });
  await writeFile(join(out, `${name}.svg`), design.toSVG(), 'utf-8');
  await writeFile(join(out, `${name}.png`), design.toPNG({ scale }));
  console.log(`wrote ${join(out, `${name}.svg`)} and ${join(out, `${name}.png`)} (raster at ${scale}x)`);
  console.log('');
  console.log(brandInstructions(brand));
}

const invoked = process.argv[1] ? resolve(process.argv[1]) : '';
const self = resolve(fileURLToPath(import.meta.url));
if (process.platform === 'win32' ? invoked.toLowerCase() === self.toLowerCase() : invoked === self) {
  run().catch((err) => {
    console.error(err.message);
    process.exit(1);
  });
}
